"""Углублённый 11 класс, ФРП стр.17–18,41–42,72: авторские задачи."""
from author_tools import N,H,G,P
from math import sqrt
from fractions import Fraction
import ast

def _rows11b(key,data):
    out=[]
    for i,line in enumerate(data.strip().splitlines(),1):
        d,p,a,s,o=line.split('~');a=a.replace('−','-')
        if a.startswith('['):answer=ast.literal_eval(a)
        elif a.startswith('√'):answer=(sqrt(float(Fraction(a[1:].strip("()")))),{"√(1/3)":"√3/3","√(2/3)":"√6/3"}.get(a,a))
        elif '/' in a:answer=(float(Fraction(a)),a)
        else:answer=float(a)
        out.append((key+'-'+str(i),p,answer,s,o,d))
    return out

def U(n,title,data,subject=H,ref='17–18'):
    N(bank,11,n,subject,title,ref,_rows11b('a11-'+str(n),data))

